begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id) values('10000000-0000-0000-0000-000000000001');
insert into auth.identities(id,user_id,provider,provider_id,identity_data) values(gen_random_uuid(),'10000000-0000-0000-0000-000000000001','github','7001','{"sub":"7001","user_name":"owner"}');
insert into auth.sessions(id,user_id) values('50000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001');
insert into public.github_users(github_user_id,login,account_type) values(7001,'owner','User');
insert into public.organizations(github_account_id,slug,name) values(9001,'allowed','Allowed'),(9002,'other','Other');
insert into public.github_installations(organization_id,github_installation_id,account_id,account_login,account_type,installed_at)
 select id,8001,9001,'allowed','Organization',now() from public.organizations where slug='allowed';
insert into public.repositories(organization_id,installation_id,github_repository_id,owner,name,full_name)
 select organization_id,id,6001,'allowed','repo','allowed/repo' from public.github_installations;
insert into public.repository_backfills(repository_id,organization_id,status,pages_completed,last_error)
 select id,organization_id,'running',4,'private diagnostic' from public.repositories;
select is(public.complete_installation_setup('10000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001',8002,9001)->>'status','waiting_for_webhook','missing webhook returns pending without creating installation');
select is((select count(*) from public.organization_memberships),0::bigint,'pending callback grants nothing');
select throws_ok($$select public.complete_installation_setup('10000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001',8001,999)$$,'42501','installation is unavailable','account identity must match stored installation');
select is(public.complete_installation_setup('10000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001',8001,9001)->>'status','ready','verified admin enters available installation');
select is(public.complete_installation_setup('10000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001',8001,9001)->>'status','ready','repeat callback safe');
select is(public.complete_installation_setup('10000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001',8001,9001)->'repositories'->0->>'status','running','partial backfill reported without blocking entry');
select ok(not (public.complete_installation_setup('10000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001',8001,9001)::text like '%private diagnostic%'),'private backfill errors never sent to browser');
select is((select pages_completed from public.repository_backfills),4,'refresh preserves cursor progress');
select is((select count(*) from public.organization_memberships),1::bigint,'no duplicate membership');
select is((select count(*) from public.background_jobs),0::bigint,'normal callbacks never restart setup');
select set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000001","role":"authenticated","session_id":"50000000-0000-0000-0000-000000000001"}',true);
set local role authenticated;
select is(public.get_installation_setup_subject()->>'githubUserId','7001','subject derives from Auth identity');
select is((select count(*) from public.organizations),1::bigint,'verified admin only sees own organization');
select is(public.get_signed_in_access()->'organizations'->0->>'installationId','8001','account screen receives verified team entry link');
select ok(not has_function_privilege('authenticated','public.complete_installation_setup(uuid,uuid,bigint,bigint,boolean)','EXECUTE'),'browser cannot grant itself access');
select ok(not has_function_privilege('anon','public.get_installation_setup_subject()','EXECUTE'),'anonymous caller cannot obtain subject');
reset role;
select public.expire_installation_setup_access('10000000-0000-0000-0000-000000000001',8001);
set local role authenticated;
select is((select count(*) from public.organizations),0::bigint,'denied GitHub recheck immediately expires RLS access');
select is(public.get_signed_in_access()->'organizations'->0->>'installationId','8001','expired lease retains remembered team link without granting data access');
select is(jsonb_array_length(public.get_signed_in_access()->'organizations'),1,'directory never discovers unrelated organizations');
reset role;
insert into public.github_installations(organization_id,github_installation_id,account_id,account_login,account_type,installed_at)
 select id,8002,9002,'other','Organization',now() from public.organizations where slug='other';
select public.complete_installation_setup('10000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001',8002,9002);
select public.expire_installation_setup_access('10000000-0000-0000-0000-000000000001',8002);
set local role authenticated;
select is(jsonb_array_length(public.get_signed_in_access()->'organizations'),2,'both connected teams remain selectable after their leases expire');
select is((select count(*) from public.organizations),0::bigint,'remembering two teams grants access to neither expired tenant');
reset role;
update public.organization_memberships set installation_verified_until=now()+interval '5 minutes';
update public.github_installations set status='suspended';
set local role authenticated;
select is((select count(*) from public.organizations),0::bigint,'suspended installation denies RLS even before lease expiry');
select is(jsonb_array_length(public.get_signed_in_access()->'organizations'),0,'suspended installation disappears from directory');
reset role;
update public.github_installations set status='active';
update public.organization_memberships set active=false;
set local role authenticated;
select is(jsonb_array_length(public.get_signed_in_access()->'organizations'),0,'explicitly revoked membership disappears from directory');
reset role;
select throws_ok($$select public.complete_installation_setup('10000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001',8001,9001)$$,'42501','membership is revoked','explicit local removal cannot be undone by refreshing callback');
update public.organization_memberships set active=true;
delete from auth.sessions;
select throws_ok($$select public.complete_installation_setup('10000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001',8001,9001)$$,'42501','session is not active','logout during GitHub verification prevents grant');
select * from finish();
rollback;
